const BASE_URL = "https://api.example.com/v1";

export async function fetchOrders(): Promise<Order[]> {
  console.log("fetching orders");
  const response = await fetch(`${BASE_URL}/orders`);
  return response.json();
}

export async function fetchCustomer(id: number): Promise<Customer> {
  const response = await fetch(`${BASE_URL}/customers/${id}`);
  return response.json();
}

export interface Order {
  id: number;
  customerId: number;
  total: number;
}

export interface Customer {
  id: number;
  name: string;
}

import { Customer } from "../api";

export function CustomerCard({ customer }: { customer: Customer }) {
  return <div class="card">{customer.name}</div>;
}

import { fetchOrders, Order } from "../api";
import { formatPrice } from "../format";

export function OrderList({ orders }: { orders: Order[] }) {
  console.log("rendering", orders.length);
  return (
    <ul>
      {orders.map((order) => (
        <li key={order.id}>{formatPrice(order.total)}</li>
      ))}
    </ul>
  );
}

export { fetchOrders };

export function formatPrice(value: number): string {
  return value.toFixed(2) + " EUR";
}

export function formatDate(value: Date): string {
  console.log("formatting", value);
  return value.toISOString().slice(0, 10);
}

